#include <waitoff.hxx>
ScWaitCursorOff::ScWaitCursorOff( vcl::Window* pWinP )
        :
        pWin( pWinP ),
        nWaiters(0)
{
    if ( pWin )
    {
        while ( pWin->IsWait() )
        {
            nWaiters++;
            pWin->LeaveWait();
        }
    }
}
ScWaitCursorOff::~ScWaitCursorOff()
{
    if ( pWin )
    {
        while ( nWaiters )
        {
            nWaiters--;
            pWin->EnterWait();
        }
    }
}
